16	/// A node in the untyped syntax tree.
17	#[derive(Clone, Eq, PartialEq, Hash)]
18	pub struct SyntaxNode {
19	    /// The underlying node data, potentially with wrapped warning messages.
20	    data: Node,
21	    /// The node's span, at the top-level to guarantee efficient access.
22	    span: Span,
23	    // We would love to move the `SyntaxKind` up here as well, but keeping it in
24	    // `Node` saves 8 bytes :/
25	}
26	
27	/// The data for nodes in the tree, plus their [`SyntaxKind`]. May actually be a
28	/// warning message wrapping a child [`Node`].
29	///
30	/// Contains the [`SyntaxKind`] at the top-level for efficient access. This
31	/// requires being careful when mutating the kind, as warnings store this type
32	/// as their child, which duplicates the kind. Deduplicating the syntax kinds
33	/// would require a whole other enum type, and makes mutable access too painful.
34	///
35	/// The only other invariant for syntax kinds is that error nodes always contain
36	/// [`SyntaxKind::Error`], but leaf and inner nodes never do. The syntax kind of
37	/// a warning depends on what it wraps.
38	///
39	/// The simplest way to get the underlying data by descending into the children
40	/// of warnings is via a loop and match like below. The [`Node::node_ref`]
41	/// helper does this for the by-reference case, but mutation is usually more
42	/// involved, so only gets the [`Node::inner_mut`] helper.
43	/// ```ignore
44	/// let mut data = &mut node.data;
45	/// let value = loop {
46	///     match data {
47	///         Leaf(_, _) | Inner(_, _) | Error(_, _) => break "value",
48	///         Warning(warn, _) => data = &mut Arc::make_mut(warn).child,
49	///     }
50	/// };
51	/// ```
52	#[derive(Clone, Eq, PartialEq, Hash)]
53	enum Node {
54	    Leaf(EcoString, SyntaxKind),
55	    Inner(Arc<InnerNode>, SyntaxKind),
56	    Error(Arc<ErrorNode>, SyntaxKind),
57	    Warning(Arc<WarningWrapper>, SyntaxKind),
58	}
59	
60	/// Data attached to a node, accessed by reference via [`Node::node_ref`].
61	enum NodeRef<'a> {
62	    Leaf(&'a EcoString),
63	    Inner(&'a Arc<InnerNode>),
64	    Error(&'a Arc<ErrorNode>),
65	}
66	
67	impl Node {
68	    /// Access the underlying node data by reference, descending past warnings.
69	    fn node_ref(&self) -> NodeRef<'_> {
70	        let mut data = self;
71	        loop {
72	            match data {
73	                Node::Leaf(text, _) => break NodeRef::Leaf(text),
74	                Node::Inner(inner, _) => break NodeRef::Inner(inner),
75	                Node::Error(err, _) => break NodeRef::Error(err),
76	                Node::Warning(warn, _) => data = &warn.child,
77	            }
78	        }
79	    }
80	
81	    /// Access an inner node mutably, descending past warnings.
82	    fn inner_mut(&mut self) -> Option<&mut InnerNode> {
83	        let mut data = self;
84	        loop {
85	            match data {
86	                Node::Leaf(_, _) | Node::Error(_, _) => break None,
87	                Node::Inner(inner, _) => break Some(Arc::make_mut(inner)),
88	                Node::Warning(warn, _) => data = &mut Arc::make_mut(warn).child,
89	            }
90	        }
91	    }
92	
93	    /// Access the hints for an error or warning mutably.
94	    fn hints_mut(&mut self) -> Option<&mut EcoVec<(EcoString, Option<SubRange>)>> {
95	        match self {
96	            Node::Leaf(_, _) | Node::Inner(_, _) => None,
97	            Node::Error(err, _) => Some(&mut Arc::make_mut(err).hints),
98	            Node::Warning(warn, _) => Some(&mut Arc::make_mut(warn).hints),
99	        }
100	    }
101	}
102	
103	impl SyntaxNode {
104	    /// Create a new leaf node.
105	    #[track_caller]
106	    pub fn leaf(kind: SyntaxKind, text: impl Into<EcoString>) -> Self {
107	        debug_assert!(!kind.is_error());
108	        Self {
109	            data: Node::Leaf(text.into(), kind),
110	            span: Span::detached(),
111	        }
112	    }
113	
114	    /// Create a new inner node with children.
115	    #[track_caller]
116	    pub fn inner(kind: SyntaxKind, children: Vec<SyntaxNode>) -> Self {
117	        debug_assert!(!kind.is_error());
118	        Self {
119	            data: Node::Inner(Arc::new(InnerNode::new(children)), kind),
120	            span: Span::detached(),
121	        }
122	    }
123	
124	    /// Create a new error node with a user-presentable message for the given
125	    /// text. Note that the message is the first argument, and the text causing
126	    /// the error is the second argument.
127	    pub fn error(message: impl Into<EcoString>, text: impl Into<EcoString>) -> Self {
128	        Self {
129	            data: Node::Error(
130	                Arc::new(ErrorNode::new(message.into(), text.into())),
131	                SyntaxKind::Error,
132	            ),
133	            span: Span::detached(),
134	        }
135	    }
136	
137	    /// Add a warning message to an existing node.
138	    ///
139	    /// Calling this requires that we either recursively update the parent
140	    /// node's `diagnosis` (as in reparsing) or we are in the process of
141	    /// constructing the parent (as in normal parsing).
142	    pub fn warn(&mut self, message: impl Into<EcoString>) {
143	        let kind = self.kind();
144	        let child = std::mem::replace(&mut self.data, Node::Leaf(EcoString::new(), kind));
145	        let warn = Arc::new(WarningWrapper::new(child, None, message.into()));
146	        self.data = Node::Warning(warn, kind);
147	    }
148	
149	    /// Add a warning around this node at a particular sub-range of the node's
150	    /// text. Panics if the range is empty or exceeds the length of the wrapped
151	    /// text.
152	    ///
153	    /// Calling this requires that we either recursively update the parent
154	    /// node's `diagnosis` (as in reparsing) or we are in the process of
155	    /// constructing the parent (as in normal parsing).
156	    #[track_caller]
157	    pub fn warn_at(
158	        &mut self,
159	        Range { start, end }: Range<usize>,
160	        message: impl Into<EcoString>,
161	    ) {
162	        assert!(end <= self.len()); // This isn't checked by `SubRange::new`.
163	        let sub_range = SubRange::new(start, end).expect("a valid sub-range");
164	        let kind = self.kind();
165	        let child = std::mem::replace(&mut self.data, Node::Leaf(EcoString::new(), kind));
166	        let warn = Arc::new(WarningWrapper::new(child, Some(sub_range), message.into()));
167	        self.data = Node::Warning(warn, kind);
168	    }
169	
170	    /// Add a user-presentable hint to an existing error or warning. Panics if
171	    /// this is not an error or warning.
172	    #[track_caller]
173	    pub fn hint(&mut self, hint: impl Into<EcoString>) {
174	        let hints = self.data.hints_mut().expect("expected an error or warning");
175	        hints.push((hint.into(), None));
176	    }
177	
178	    /// Add a user-presentable hint to an existing error or warning at a
179	    /// sub-range of the text. Panics if the range is empty or exceeds the
180	    /// length of the wrapped text. Panics if this is not an error or warning
181	    /// node.
182	    #[track_caller]
183	    pub fn hint_at(
184	        &mut self,
185	        Range { start, end }: Range<usize>,
186	        hint: impl Into<EcoString>,
187	    ) {
188	        assert!(end <= self.len()); // This isn't checked by `SubRange::new`.
189	        let sub_range = SubRange::new(start, end).expect("a valid sub-range");
190	        let hints = self.data.hints_mut().expect("expected an error or warning");
191	        hints.push((hint.into(), Some(sub_range)));
192	    }
193	
194	    /// Add multiple hints while building an error or warning. Panics if this is
195	    /// not an error or warning.
196	    #[track_caller]
197	    pub fn with_hints(mut self, new_hints: impl IntoIterator<Item = EcoString>) -> Self {
198	        let hints = self.data.hints_mut().expect("expected an error or warning");
199	        let iter = new_hints.into_iter().map(|h| (h, None));
200	        hints.extend(iter);
201	        self
202	    }
203	
204	    /// Create a dummy node of the given kind.
205	    ///
206	    /// Panics if `kind` is [`SyntaxKind::Error`].
207	    #[track_caller]
208	    pub const fn placeholder(kind: SyntaxKind) -> Self {
209	        if kind.is_error() {
210	            panic!("cannot create error placeholder");
211	        }
212	        Self {
213	            data: Node::Leaf(EcoString::new(), kind),
214	            span: Span::detached(),
215	        }
216	    }
217	
218	    /// The type of the node.
219	    pub fn kind(&self) -> SyntaxKind {
220	        match self.data {
221	            Node::Leaf(_, kind)
222	            | Node::Inner(_, kind)
223	            | Node::Error(_, kind)
224	            | Node::Warning(_, kind) => kind,
225	        }
226	    }
227	
228	    /// Return `true` if the length is 0.
229	    pub fn is_empty(&self) -> bool {
230	        self.len() == 0
231	    }
232	
233	    /// The byte length of the node in the source text.
234	    pub fn len(&self) -> usize {
235	        match self.data.node_ref() {
236	            NodeRef::Leaf(text) => text.len(),
237	            NodeRef::Inner(inner) => inner.len,
238	            NodeRef::Error(err) => err.text.len(),
239	        }
240	    }
241	
242	    /// The span of the node.
243	    pub fn span(&self) -> Span {
244	        self.span
245	    }
246	
247	    /// The text of the node if it is a leaf or error node.
248	    ///
249	    /// Returns the empty string if this is an inner node.
250	    pub fn leaf_text(&self) -> &EcoString {
251	        static EMPTY: EcoString = EcoString::new();
252	        match self.data.node_ref() {
253	            NodeRef::Leaf(text) => text,
254	            NodeRef::Inner(_) => &EMPTY,
255	            NodeRef::Error(err) => &err.text,
256	        }
257	    }
258	
259	    /// Clone the full text from the node. If this is an inner node, it will
260	    /// traverse the tree to build the text which may be expensive.
261	    pub fn full_text(&self) -> EcoString {
262	        match &self.data {
263	            Node::Leaf(leaf, _) => leaf.clone(),
264	            Node::Error(err, _) => err.text.clone(),
265	            Node::Inner(_, _) | Node::Warning(_, _) => {
266	                let mut buffer = EcoString::with_capacity(self.len());
267	                self.traverse(|node| {
268	                    match node.data.node_ref() {
269	                        NodeRef::Leaf(text) => buffer.push_str(text),
270	                        NodeRef::Inner(_) => {}
271	                        NodeRef::Error(err) => buffer.push_str(&err.text),
272	                    }
273	                    node.children()
274	                });
275	                buffer
276	            }
277	        }
278	    }
279	
280	    /// The node's children.
281	    pub fn children(&self) -> std::slice::Iter<'_, SyntaxNode> {
282	        match self.data.node_ref() {
283	            NodeRef::Leaf(_) | NodeRef::Error(_) => [].iter(),
284	            NodeRef::Inner(inner) => inner.children.iter(),
285	        }
286	    }
287	
288	    /// Whether the node has diagnostic errors and/or warnings in it or its
289	    /// children. [`Diagnosis`] has public fields, so you can write
290	    /// `node.diagnosis().errors` to determine if a node is erroneous.
291	    ///
292	    /// This can be used to determine whether [`Self::errors_and_warnings`] will
293	    /// return an empty vector without traversing the tree if it will not.
294	    pub fn diagnosis(&self) -> Diagnosis {
295	        let diagnosis = match self.data.node_ref() {
296	            NodeRef::Leaf(_) => Diagnosis::default(),
297	            NodeRef::Inner(inner) => inner.diagnosis,
298	            NodeRef::Error(_) => Diagnosis { errors: true, warnings: false },
299	        };
300	        match &self.data {
301	            Node::Warning(_, _) => Diagnosis { warnings: true, errors: diagnosis.errors },
302	            _ => diagnosis,
303	        }
304	    }
305	
306	    /// The error and warning diagnostics for this node and its descendants.
307	    pub fn errors_and_warnings(&self) -> (Vec<SyntaxDiagnostic>, Vec<SyntaxDiagnostic>) {
308	        let mut errors = Vec::new();
309	        let mut warnings = Vec::new();
310	        self.traverse(|node| {
311	            let mut data = &node.data;
312	            loop {
313	                match data {
314	                    Node::Inner(inner, _) if inner.diagnosis.either() => {
315	                        break inner.children.iter();
316	                    }
317	                    Node::Leaf(_, _) | Node::Inner(_, _) => break [].iter(),
318	                    Node::Error(err, _) => {
319	                        errors.push(err.diagnostic(node.span));
320	                        break [].iter();
321	                    }
322	                    Node::Warning(warn, _) => {
323	                        warnings.push(warn.diagnostic(node.span));
324	                        data = &warn.child;
325	                    }
326	                }
327	            }
328	        });
329	        (errors, warnings)
330	    }
331	
332	    /// Set a synthetic span for the node and all its descendants, and add hints
333	    /// with the original indices to any syntax errors or warnings.
334	    pub fn synthesize(&mut self, span: Span) {
335	        self.synthesize_with(
336	            0,
337	            &|_, _| span,
338	            // Sub-ranges are removed since the overall range is not accurate.
339	            &|_, sub_range| *sub_range = None,
340	            &|offset, len| {
341	                Some(if len == 0 {
342	                    eco_format!("at index `{offset}`")
343	                } else {
344	                    eco_format!("from index `{offset}` to `{}`", offset + len)
345	                })
346	            },
347	        );
348	    }
349	
350	    /// Set a raw range span for each node.
351	    ///
352	    /// The range is determined by mapping the node's ranges through the given
353	    /// `mapper`.
354	    ///
355	    /// Returns an error with the mapper's length if it was shorter than the
356	    /// length of the source text.
357	    pub fn synthesize_mapped(
358	        &mut self,
359	        id: FileId,
360	        mapper: &RangeMapper,
361	    ) -> Result<(), EcoString> {
362	        if self.len() > mapper.total_len() {
363	            // TODO: Should we error if not exactly equal?
364	            return Err(eco_format!(
365	                "text length ({}) is greater than mapper length ({})",
366	                self.len(),
367	                mapper.total_len(),
368	            ));
369	        }
370	        self.synthesize_with(
371	            0,
372	            &|offset, len| Span::from_range(id, mapper.map(offset..offset + len)),
373	            &|offset, sub_range| {
374	                if let Some(sr) = sub_range {
375	                    *sr = mapper.map_sub_range(offset, *sr);
376	                }
377	            },
378	            &|_, _| None,
379	        );
380	        Ok(())
381	    }
382	
383	    /// Set a custom span for each node given its offset and length, and update
384	    /// any sub-ranges based on their offset.
385	    ///
386	    /// Should be called with `offset = 0` on the root node.
387	    fn synthesize_with(
388	        &mut self,
389	        mut offset: usize,
390	        map_span: &impl Fn(usize, usize) -> Span,
391	        update_sub_range: &impl Fn(usize, &mut Option<SubRange>),
392	        add_hint: &impl Fn(usize, usize) -> Option<EcoString>,
393	    ) {
394	        let len = self.len();
395	        self.span = map_span(offset, len);
396	        let mut data = &mut self.data;
397	        loop {
398	            match data {
399	                Node::Leaf(_, _) => break,
400	                Node::Inner(inner, _) => {
401	                    let inner = Arc::make_mut(inner);
402	                    inner.upper = self.span.number();
403	                    for child in &mut inner.children {
404	                        child.synthesize_with(
405	                            offset,
406	                            map_span,
407	                            update_sub_range,
408	                            add_hint,
409	                        );
410	                        offset += child.len();
411	                    }
412	                    break;
413	                }
414	                Node::Error(err, _) => {
415	                    let err = Arc::make_mut(err);
416	                    for (_hint, sub_range) in err.hints.make_mut() {
417	                        update_sub_range(offset, sub_range);
418	                    }
419	                    if let Some(hint) = add_hint(offset, len) {
420	                        err.hints.push((hint, None));
421	                    }
422	                    break;
423	                }
424	                Node::Warning(warn, _) => {
425	                    let warn = Arc::make_mut(warn);
426	                    let (orig_offset, orig_len) = match warn.sub_range {
427	                        Some(sub_range) => {
428	                            let range = sub_range.to_absolute(offset);
429	                            (range.start, range.len())
430	                        }
431	                        None => (offset, len),
432	                    };
433	                    update_sub_range(offset, &mut warn.sub_range);
434	                    for (_hint, sub_range) in warn.hints.make_mut() {
435	                        update_sub_range(offset, sub_range);
436	                    }
437	                    if let Some(hint) = add_hint(orig_offset, orig_len) {
438	                        warn.hints.push((hint, None));
439	                    }
440	                    data = &mut warn.child;
441	                }
442	            }
443	        }
444	    }
