446	    /// Whether the two syntax nodes are the same apart from spans.
447	    pub fn spanless_eq(&self, other: &Self) -> bool {
448	        self.kind() == other.kind() && {
449	            let mut data_a = &self.data;
450	            let mut data_b = &other.data;
451	            loop {
452	                match (data_a, data_b) {
453	                    (Node::Leaf(a, _), Node::Leaf(b, _)) => break a == b,
454	                    (Node::Inner(a, _), Node::Inner(b, _)) => {
455	                        break a.spanless_eq(b);
456	                    }
457	                    (Node::Error(a, _), Node::Error(b, _)) => break a == b,
458	                    (Node::Warning(a, _), Node::Warning(b, _))
459	                        if a.sub_range == b.sub_range
460	                            && a.message == b.message
461	                            && a.hints == b.hints =>
462	                    {
463	                        data_a = &a.child;
464	                        data_b = &b.child;
465	                    }
466	                    _ => break false,
467	                }
468	            }
469	        }
470	    }
471	}
