473	impl SyntaxNode {
474	    /// Convert the child to another kind.
475	    ///
476	    /// Panics if trying to convert to or from an error.
477	    #[track_caller]
478	    pub(super) fn convert_to_kind(&mut self, new_kind: SyntaxKind) {
479	        if new_kind.is_error() {
480	            panic!("cannot convert to an error, use `convert_to_error` instead");
481	        } else if self.kind().is_error() {
482	            // `.kind()` checks both errors and warnings that wrap errors.
483	            panic!("cannot convert an error to a different kind");
484	        }
485	        // Must assign through warnings as well, since they duplicate the kind.
486	        let mut data = &mut self.data;
487	        loop {
488	            match data {
489	                Node::Leaf(_, kind) | Node::Inner(_, kind) => {
490	                    *kind = new_kind;
491	                    break;
492	                }
493	                Node::Error(_, _) => unreachable!(),
494	                Node::Warning(warn, kind) => {
495	                    *kind = new_kind;
496	                    data = &mut Arc::make_mut(warn).child;
497	                }
498	            }
499	        }
500	    }
501	
502	    /// Convert the child to an error, if it isn't already one.
503	    pub(super) fn convert_to_error(&mut self, message: impl Into<EcoString>) {
504	        if !self.kind().is_error() {
505	            let text = std::mem::take(self).full_text();
506	            *self = SyntaxNode::error(message.into(), text);
507	        }
508	    }
509	
510	    /// Convert the child to an error stating that the given thing was
511	    /// expected, but the current kind was found.
512	    pub(super) fn expected(&mut self, expected: &str) {
513	        let kind = self.kind();
514	        self.convert_to_error(eco_format!("expected {expected}, found {}", kind.name()));
515	        if kind.is_keyword() && matches!(expected, "identifier" | "pattern") {
516	            self.hint(eco_format!(
517	                "keyword `{text}` is not allowed as an identifier; try `{text}_` instead",
518	                text = self.leaf_text(),
519	            ));
520	        }
521	    }
522	
523	    /// Convert the child to an error stating it was unexpected.
524	    pub(super) fn unexpected(&mut self) {
525	        self.convert_to_error(eco_format!("unexpected {}", self.kind().name()));
526	    }
527	
528	    /// Assign spans to each node.
529	    pub(super) fn numberize(
530	        &mut self,
531	        id: FileId,
532	        within: Range<u64>,
533	    ) -> NumberingResult {
534	        if within.start >= within.end {
535	            Err(Unnumberable)
536	        } else if let Some(inner) = self.data.inner_mut() {
537	            inner.numberize(Some(&mut self.span), id, None, within)
538	        } else {
539	            self.span =
540	                Span::from_number(id, SpanNumber((within.start + within.end) / 2));
541	            Ok(())
542	        }
543	    }
544	
545	    /// Traverse the tree in-order, calling `f` on each node before recursing on
546	    /// the returned node slice (normally just `node.children()`).
547	    ///
548	    /// Note that `f` can prune the traversal at any point by yielding
549	    /// `[].iter()` instead of the actual children slice of an inner node.
550	    pub(super) fn traverse(
551	        &self,
552	        mut f: impl FnMut(&Self) -> std::slice::Iter<'_, Self>,
553	    ) {
554	        fn recursive_step(
555	            node: &SyntaxNode,
556	            f: &mut impl FnMut(&SyntaxNode) -> std::slice::Iter<'_, SyntaxNode>,
557	        ) {
558	            for child in f(node) {
559	                recursive_step(child, f);
560	            }
561	        }
562	        // We pass in `&mut impl FnMut` so our caller doesn't have to.
563	        recursive_step(self, &mut f);
564	    }
565	
566	    /// Whether this is a leaf node.
567	    pub(super) fn is_leaf(&self) -> bool {
568	        matches!(self.data.node_ref(), NodeRef::Leaf(_))
569	        // TODO: Should we also treat non-empty errors as leaves?
570	    }
571	
572	    /// Whether this is an inner node.
573	    pub(super) fn is_inner(&self) -> bool {
574	        matches!(self.data.node_ref(), NodeRef::Inner(_))
575	    }
576	
577	    /// The number of descendants, including the node itself.
578	    pub(super) fn descendants(&self) -> usize {
579	        match self.data.node_ref() {
580	            NodeRef::Leaf(_) | NodeRef::Error(_) => 1,
581	            NodeRef::Inner(inner) => inner.descendants,
582	        }
583	    }
584	
585	    /// The node's children, mutably.
586	    pub(super) fn children_mut(&mut self) -> &mut [SyntaxNode] {
587	        if let Some(inner) = self.data.inner_mut() {
588	            &mut inner.children
589	        } else {
590	            &mut []
591	        }
592	    }
593	
594	    /// The upper bound of assigned numbers in this subtree.
595	    pub(super) fn upper(&self) -> u64 {
596	        match self.data.node_ref() {
597	            NodeRef::Leaf(_) | NodeRef::Error(_) => self.span.number() + 1,
598	            NodeRef::Inner(inner) => inner.upper,
599	        }
600	    }
601	
602	    /// Access an inner node mutably for incremental reparsing. Also returns the
603	    /// node's span and syntax kind since those are needed.
604	    ///
605	    /// Unlike [`Node::inner_mut`], this does not descend past wrapped warnings
