649	pub(super) struct InnerNode {
650	    /// The byte length of the node in the source.
651	    pub len: usize,
652	    /// The number of nodes in the whole subtree, including this node.
653	    pub descendants: usize,
654	    /// Whether this node or any of its children contain an error/warning
655	    /// diagnostic.
656	    pub diagnosis: Diagnosis,
657	    /// The upper bound of this node's numbering range.
658	    pub upper: u64,
659	    /// This node's children, losslessly make up this node.
660	    pub children: Vec<SyntaxNode>,
661	}
662	
663	impl InnerNode {
664	    /// Create a new inner node with the given children.
665	    fn new(children: Vec<SyntaxNode>) -> Self {
666	        let mut len = 0;
667	        let mut descendants = 1;
668	        let mut diagnosis = Diagnosis::default();
669	
670	        for child in &children {
671	            len += child.len();
672	            descendants += child.descendants();
673	            diagnosis = diagnosis.or(child.diagnosis());
674	        }
675	
676	        Self { len, descendants, diagnosis, upper: 0, children }
677	    }
678	
679	    /// Assign span numbers `within` an interval to this node's subtree or just
680	    /// a `range` of its children.
681	    pub fn numberize(
682	        &mut self,
683	        span: Option<&mut Span>,
684	        id: FileId,
685	        range: Option<Range<usize>>,
686	        within: Range<u64>,
687	    ) -> NumberingResult {
688	        // Determine how many nodes we will number.
689	        let descendants = match &range {
690	            Some(range) if range.is_empty() => return Ok(()),
691	            Some(range) => self.children[range.clone()]
692	                .iter()
693	                .map(SyntaxNode::descendants)
694	                .sum::<usize>(),
695	            None => self.descendants,
696	        };
697	
698	        // Determine the distance between two neighbouring assigned numbers. If
699	        // possible, we try to fit all numbers into the left half of `within`
700	        // so that there is space for future insertions.
701	        let space = within.end - within.start;
702	        let mut stride = space / (2 * descendants as u64);
703	        if stride == 0 {
704	            stride = space / descendants as u64;
705	            if stride == 0 {
706	                return Err(Unnumberable);
707	            }
708	        }
709	
710	        // Number the node itself.
711	        let mut start = within.start;
712	        if let Some(span) = span {
713	            debug_assert!(range.is_none(), "`node_span` and `range` are exclusive");
714	            let end = start + stride;
715	            *span = Span::from_number(id, SpanNumber((start + end) / 2));
716	            self.upper = within.end;
717	            start = end;
718	        }
719	
720	        // Number the children.
721	        let len = self.children.len();
722	        for child in &mut self.children[range.unwrap_or(0..len)] {
723	            let end = start + child.descendants() as u64 * stride;
724	            child.numberize(id, start..end)?;
725	            start = end;
726	        }
727	
728	        Ok(())
729	    }
730	
731	    /// Whether the two inner nodes are the same apart from spans.
732	    fn spanless_eq(&self, other: &Self) -> bool {
733	        self.len == other.len
734	            && self.descendants == other.descendants
735	            && self.diagnosis == other.diagnosis
736	            && self.children.len() == other.children.len()
737	            && self
738	                .children
739	                .iter()
740	                .zip(&other.children)
741	                .all(|(a, b)| a.spanless_eq(b))
742	    }
743	
744	    /// Write with debug formatting using the node's syntax kind.
745	    fn debug_fmt_kind(&self, f: &mut Formatter, kind: SyntaxKind) -> fmt::Result {
746	        write!(f, "{kind:?}: {}", self.len)?;
747	        if !self.children.is_empty() {
748	            f.write_str(" ")?;
749	            f.debug_list().entries(&self.children).finish()?;
750	        }
751	        Ok(())
752	    }
753	}
