899	    /// Write with debug formatting using the node's overall span.
900	    ///
901	    /// The overall span is needed to correctly format sub-ranges. If the syntax
902	    /// tree used range-mapping ([`SyntaxNode::synthesize_mapped`]), we can't
903	    /// know the actual text being warned/hinted at without accessing the source
904	    /// file. So instead of showing the text included by the sub-range, we fall
905	    /// back to showing the mapped indices of the sub-range.
906	    fn debug_fmt_span(&self, f: &mut Formatter, span: Span) -> fmt::Result {
907	        let full_text = LazyCell::new(|| {
908	            let data = self.child.clone();
909	            let temp_node = SyntaxNode { data, span: Span::detached() };
910	            temp_node.full_text()
911	        });
912	        let debug_field = |field, message, sub_range: Option<SubRange>| {
913	            // Inner closure has `move`, so need to explicitly capture by ref.
914	            let full_text = &full_text;
915	            debug(move |f| {
916	                if let Some(sr) = sub_range {
917	                    if let SpanKind::Range { id: _, range } = span.get() {
918	                        let new_range = sr.to_absolute(range.start);
919	                        write!(f, "{field} @mapped({new_range:?}): {message:?}")
920	                    } else {
921	                        let selected = &full_text[sr.to_relative()];
922	                        write!(f, "{field} @text({selected:?}): {message:?}")
923	                    }
924	                } else {
925	                    write!(f, "{field}: {message:?}")
926	                }
927	            })
928	        };
929	
930	        write!(f, "Warning: ")?;
931	        // Use `debug_set` instead of `debug_struct` so we don't have to add a
932	        // field name when outputting the child.
933	        let mut out = f.debug_set();
934	        out.entry(&debug_field("message", &self.message, self.sub_range));
935	        for (hint, sub_range) in &self.hints {
936	            out.entry(&debug_field("hint", hint, *sub_range));
937	        }
938	        out.entry(&debug(move |f| self.child.debug_fmt_span(f, span)));
939	        out.finish()
940	    }
941	}
