943	/// Map a vector of hints with optional sub-ranges to one with optional
944	/// diagnostic spans derived from a parent span.
945	fn build_diagnostic_hints(
946	    parent_span: Span,
947	    hints: &EcoVec<(EcoString, Option<SubRange>)>,
948	) -> EcoVec<Spanned<EcoString, DiagSpan>> {
949	    hints
950	        .iter()
951	        .map(|(message, sub_range)| {
952	            let msg = message.clone();
953	            match *sub_range {
954	                Some(sr) => Spanned::new(msg, DiagSpan::from_span(parent_span, Some(sr))),
955	                None => Spanned::detached(msg),
956	            }
957	        })
958	        .collect()
959	}
