1015	    /// Find a descendant with the given span.
1016	    pub fn find(&self, span: Span) -> Option<Self> {
1017	        match span.get() {
1018	            SpanKind::Detached => None,
1019	            SpanKind::Number { id: _, num } => self.find_number(num),
1020	            SpanKind::Range { id: _, range } => self.find_range(range.start, range.end),
1021	        }
1022	    }
