1024	    /// Find the descendant whose span number matches the given number.
1025	    ///
1026	    /// This relies on the ordering guarantees of numbered spans:
1027	    /// - The number of a parent is smaller than the numbers of all its children
1028	    /// - The numbers of sibling nodes always increase from left to right
1029	    pub(crate) fn find_number(&self, target: SpanNumber) -> Option<Self> {
1030	        let number = self.span().number();
1031	        if number == target.0 {
1032	            return Some(self.clone());
1033	        }
1034	
1035	        // The parent of a subtree has a smaller span number than all of its
1036	        // descendants. Therefore, we can bail out early if the target span's
1037	        // number is smaller than our number.
1038	        if self.node.is_inner() && number < target.0 {
1039	            // Use `self.children()`, not `inner.children()` to preserve being
1040	            // in a `LinkedNode`.
1041	            let mut children = self.children().peekable();
1042	            while let Some(child) = children.next() {
1043	                // Every node in this child's subtree has a smaller span number than
1044	                // the next sibling. Therefore we only need to recurse if the next
1045	                // sibling's span number is larger than the target span's number.
1046	                if children.peek().is_none_or(|next| next.span().number() > target.0)
1047	                    && let Some(found) = child.find_number(target)
1048	                {
1049	                    return Some(found);
1050	                }
1051	            }
1052	        }
1053	
1054	        None
1055	    }
1056	
1057	    /// Find the descendant whose byte range matches the given range exactly.
1058	    pub(crate) fn find_range(&self, start: usize, end: usize) -> Option<Self> {
1059	        if start == self.offset && end == self.offset + self.len() {
1060	            return Some(self.clone());
1061	        }
1062	        for child in self.children() {
1063	            // Descend into the single child which fully covers the range.
1064	            if child.offset <= start && end <= child.offset + child.len() {
1065	                return child.find_range(start, end);
1066	            }
1067	        }
1068	        None
1069	    }
