1071	    /// Get the [`SyntaxMode`] we will be in when immediately after this node.
1072	    ///
1073	    /// Unlike some other `LinkedNode` methods, this does not treat all trivia
1074	    /// the same: it returns `None` for both comments and the bodies of raw text
1075	    /// and returns `Some` for whitespace (based on the parent's mode). The only
1076	    /// other way this would return `None` is when inside a partial tree, i.e.
1077	    /// one not rooted in `Markup`, `Math`, or `Code`.
1078	    ///
1079	    /// Also note that errors inherit the mode of their parent.
1080	    pub fn mode_after(&self) -> Option<SyntaxMode> {
1081	        match self.kind().mode_after() {
1082	            ModeAfter::Known(mode) => Some(mode),
1083	            // Comments and the bodies of raw text have no mode.
1084	            ModeAfter::None => None,
1085	            ModeAfter::Text if self.parent_kind() == Some(SyntaxKind::Raw) => None,
1086	            ModeAfter::RawDelim if self.index == 0 => None,
1087	            // Text not under raw is always markup.
1088	            ModeAfter::Text => Some(SyntaxMode::Markup),
1089	            // An opening dollar sign starts math mode.
1090	            ModeAfter::Dollar if self.index == 0 => Some(SyntaxMode::Math),
1091	            // Spaces at the left/right of an equation are still in math mode.
1092	            ModeAfter::Space if self.parent_kind() == Some(SyntaxKind::Equation) => {
1093	                Some(SyntaxMode::Math)
1094	            }
1095	            // The position after something embedded with a hash is still code.
1096	            ModeAfter::Embeddable
1097	                if self
1098	                    .prev_sibling_with_trivia()
1099	                    .is_some_and(|prev| prev.kind() == SyntaxKind::Hash) =>
1100	            {
1101	                Some(SyntaxMode::Code)
1102	            }
1103	            // Otherwise, we're simply based on our parent's mode.
1104	            ModeAfter::Parent
1105	            | ModeAfter::RawDelim
1106	            | ModeAfter::Space
1107	            | ModeAfter::Dollar
1108	            | ModeAfter::Embeddable => self.parent_mode(),
1109	        }
1110	    }
