1112	    /// Get the [`SyntaxMode`] we will be in when immediately after the parent
1113	    /// of this node.
1114	    pub fn parent_mode(&self) -> Option<SyntaxMode> {
1115	        self.parent().and_then(Self::mode_after)
1116	    }
1117	}
