1199	/// Access to leaves.
1200	impl LinkedNode<'_> {
1201	    /// Get the rightmost non-trivia leaf before this node.
1202	    pub fn prev_leaf(&self) -> Option<Self> {
1203	        let mut node = self.clone();
1204	        while let Some(prev) = node.prev_sibling() {
1205	            if let Some(leaf) = prev.rightmost_leaf() {
1206	                return Some(leaf);
1207	            }
1208	            node = prev;
1209	        }
1210	        self.parent()?.prev_leaf()
1211	    }
1212	
1213	    /// Find the leftmost contained non-trivia leaf.
1214	    pub fn leftmost_leaf(&self) -> Option<Self> {
1215	        if self.is_leaf() && !self.kind().is_trivia() && !self.kind().is_error() {
1216	            return Some(self.clone());
1217	        }
1218	
1219	        for child in self.children() {
1220	            if let Some(leaf) = child.leftmost_leaf() {
1221	                return Some(leaf);
1222	            }
1223	        }
1224	
1225	        None
1226	    }
1227	
1228	    /// Get the leaf immediately before the specified byte offset.
1229	    fn leaf_before(&self, cursor: usize) -> Option<Self> {
1230	        if self.node.children().len() == 0 && cursor <= self.offset + self.len() {
1231	            return Some(self.clone());
1232	        }
1233	
1234	        let mut offset = self.offset;
1235	        let count = self.node.children().len();
1236	        for (i, child) in self.children().enumerate() {
1237	            let len = child.len();
1238	            if (offset < cursor && cursor <= offset + len)
1239	                || (offset == cursor && i + 1 == count)
1240	            {
1241	                return child.leaf_before(cursor);
1242	            }
1243	            offset += len;
1244	        }
1245	
1246	        None
1247	    }
1248	
1249	    /// Get the leaf after the specified byte offset.
1250	    fn leaf_after(&self, cursor: usize) -> Option<Self> {
1251	        if self.node.children().len() == 0 && cursor < self.offset + self.len() {
1252	            return Some(self.clone());
1253	        }
1254	
1255	        let mut offset = self.offset;
1256	        for child in self.children() {
1257	            let len = child.len();
1258	            if offset <= cursor && cursor < offset + len {
1259	                return child.leaf_after(cursor);
1260	            }
1261	            offset += len;
1262	        }
1263	
1264	        None
1265	    }
1266	
1267	    /// Get the leaf at the specified byte offset.
1268	    pub fn leaf_at(&self, cursor: usize, side: Side) -> Option<Self> {
1269	        match side {
1270	            Side::Before => self.leaf_before(cursor),
1271	            Side::After => self.leaf_after(cursor),
1272	        }
1273	    }
1274	
1275	    /// Find the rightmost contained non-trivia leaf.
1276	    pub fn rightmost_leaf(&self) -> Option<Self> {
1277	        if self.is_leaf() && !self.kind().is_trivia() {
1278	            return Some(self.clone());
1279	        }
1280	
1281	        for child in self.children().rev() {
1282	            if let Some(leaf) = child.rightmost_leaf() {
1283	                return Some(leaf);
1284	            }
1285	        }
1286	
1287	        None
1288	    }
1289	
1290	    /// Get the leftmost non-trivia leaf after this node.
1291	    pub fn next_leaf(&self) -> Option<Self> {
1292	        let mut node = self.clone();
1293	        while let Some(next) = node.next_sibling() {
1294	            if let Some(leaf) = next.leftmost_leaf() {
1295	                return Some(leaf);
1296	            }
1297	            node = next;
1298	        }
1299	        self.parent()?.next_leaf()
1300	    }
1301	}
