1319	/// An iterator over the children of a linked node.
1320	pub struct LinkedChildren<'a> {
1321	    /// The parent whose children we're iterating.
1322	    parent: Rc<LinkedNode<'a>>,
1323	    /// The underlying syntax nodes and their indices.
1324	    iter: std::iter::Enumerate<std::slice::Iter<'a, SyntaxNode>>,
1325	    /// The byte offset of the next child's start.
1326	    front: usize,
1327	    /// The byte offset after the final child.
1328	    back: usize,
1329	}
1330	
1331	impl<'a> Iterator for LinkedChildren<'a> {
1332	    type Item = LinkedNode<'a>;
1333	
1334	    fn next(&mut self) -> Option<Self::Item> {
1335	        let (index, node) = self.iter.next()?;
1336	        let offset = self.front;
1337	        self.front += node.len();
1338	        Some(LinkedNode {
1339	            node,
1340	            parent: Some(self.parent.clone()),
1341	            index,
1342	            offset,
1343	        })
1344	    }
1345	
1346	    fn size_hint(&self) -> (usize, Option<usize>) {
1347	        self.iter.size_hint()
1348	    }
1349	}
