1351	impl DoubleEndedIterator for LinkedChildren<'_> {
1352	    fn next_back(&mut self) -> Option<Self::Item> {
1353	        let (index, node) = self.iter.next_back()?;
1354	        self.back -= node.len();
1355	        Some(LinkedNode {
1356	            node,
1357	            parent: Some(self.parent.clone()),
1358	            index,
1359	            offset: self.back,
1360	        })
1361	    }
1362	}
