1580	    /// Return a vector of the span numbers from an in-order traversal of the
1581	    /// tree.
1582	    fn span_numbers(root: &SyntaxNode) -> Vec<u64> {
1583	        let mut vec = vec![];
1584	        root.traverse(|node| {
1585	            vec.push(node.span().number());
1586	            node.children()
1587	        });
1588	        vec
