1592	    #[test]
1593	    #[expect(clippy::zero_prefixed_literal)]
1594	    fn test_numberize_basic() {
1595	        let id = FileId::new_for_test("numberize_basic");
1596	
1597	        // Simplest actual example.
1598	        let mut root = crate::parse("A");
1599	        assert_eq!(format!("{root:?}"), "Markup: 1 [Text: \"A\"]");
1600	        let range_numberings = [
1601	            (2..(2 + 02), [2, 3]), // +0, +1
1602	            (2..(2 + 07), [2, 3]),
1603	            (2..(2 + 08), [3, 5]), // +1, +2
1604	            (2..(2 + 11), [3, 5]),
1605	            (2..(2 + 12), [3, 6]),  // +1, +3
1606	            (2..(2 + 16), [4, 8]),  // +2, +4
1607	            (2..(2 + 20), [4, 9]),  // +2, +5
1608	            (2..(2 + 24), [5, 11]), // +3, +6
1609	            (Span::FULL, {
1610	                let Range { start, end } = Span::FULL;
1611	                let desc = root.descendants() as u64;
1612	                let stride = (end - start) / (2 * desc);
1613	                [0, 1].map(|i| start + stride / 2 + i * stride)
1614	            }),
1615	        ];
1616	        for (range, numbers) in range_numberings {
1617	            root.numberize(id, range).unwrap();
1618	            assert_eq!(span_numbers(&root), numbers);
1619	        }
1620	
1621	        // Two extra nodes.
1622	        let mut root = crate::parse(" A ");
1623	        assert_eq!(
1624	            format!("{root:?}"),
1625	            "Markup: 3 [SpaceNoNewline: \" \", Text: \"A\", SpaceNoNewline: \" \"]",
1626	        );
1627	        // This has a simple pattern since it has no nesting.
1628	        let range_numberings = [
1629	            (2..(2 + 04), [2, 3, 4, 5]), // +0, iter by 1
1630	            (2..(2 + 05), [2, 3, 4, 5]),
1631	            (2..(2 + 08), [2, 3, 4, 5]), // +0, iter by 1 (since 8/16==0, 8/8==1)
1632	            (2..(2 + 15), [2, 3, 4, 5]),
1633	            (2..(2 + 16), [3, 5, 7, 9]), // +1, iter by 2 (since 16/16==1, 16/8==2)
1634	            (2..(2 + 23), [3, 5, 7, 9]),
1635	            (2..(2 + 24), [3, 6, 9, 12]), // +1, iter by 3 (since 24/16==1, 24/8==3)
1636	            (2..(2 + 32), [4, 8, 12, 16]), // +2, iter by 4 (etc.)
1637	            (2..(2 + 40), [4, 9, 14, 19]), // +2, iter by 5
1638	            (2..(2 + 48), [5, 11, 17, 23]), // +3, iter by 6
1639	            (Span::FULL, {
1640	                let Range { start, end } = Span::FULL;
1641	                let desc = root.descendants() as u64;
1642	                let stride = (end - start) / (2 * desc);
1643	                [0, 1, 2, 3].map(|i| start + stride / 2 + i * stride)
1644	            }),
1645	        ];
1646	        for (range, numbering) in range_numberings {
1647	            root.numberize(id, range).unwrap();
1648	            assert_eq!(span_numbers(&root), numbering);
1649	        }
1650	
1651	        // More nesting and an empty inner node.
