1662	            (2..(2 + 05), [2, 3, 4, 5]),
1663	            (2..(2 + 08), [2, 3, 4, 5]),
1664	            (2..(2 + 15), [2, 3, 4, 5]), // +1, +1, iter by 1 (15/8==1)
1665	            (2..(2 + 16), [3, 4, 5, 6]), // +2, +1, iter by 1 (16/8==2)
1666	            (2..(2 + 23), [3, 4, 5, 6]),
1667	            (2..(2 + 24), [3, 5, 6, 7]), // +2, +2, iter by 1 (24/8==3)
1668	            (2..(2 + 31), [3, 5, 6, 7]),
1669	            (2..(2 + 32), [4, 7, 9, 10]), // +3, +3, iter by 1 (32/8==4)
1670	            (2..(2 + 40), [4, 8, 10, 11]),
1671	            (2..(2 + 47), [4, 8, 10, 11]),
1672	            (2..(2 + 48), [5, 9, 12, 14]),
1673	            (Span::FULL, {
1674	                let Range { start, end } = Span::FULL;
1675	                let desc = root.descendants() as u64;
1676	                let stride = (end - start) / (2 * desc);
1677	                let markup_1 = start + stride / 2;
1678	                let enum_item = markup_1 + stride * 3 / 4; // stride/4 + stride/2
1679	                let enum_marker = enum_item + stride / 2;
1680	                let markup_2 = enum_marker + stride * 3 / 8; // stride/4 + stride/8
1681	                [markup_1, enum_item, enum_marker, markup_2]
