1710	        let orig_root = crate::parse("A");
1711	        assert_eq!(format!("{orig_root:?}"), "Markup: 1 [Text: \"A\"]");
1712	
1713	        // Test replacing a single child with one or two nodes.
1714	        let one_node = &[SyntaxNode::leaf(SyntaxKind::Text, "B")];
1715	        let two_nodes = &[
1716	            SyntaxNode::leaf(SyntaxKind::Text, "C"),
1717	            SyntaxNode::leaf(SyntaxKind::Text, "D"),
1718	        ];
1719	        let range_numbering_replacements = [
1720	            // (1) The range of numbers, (2) the initial numbering for that
1721	            // range, (3) the numbering when one node replaces "A", (4) the
1722	            // numbering when two nodes replace "A".
1723	            (2..(2 + 02), [2, 3], Some([2, 3]), None),
1724	            (2..(2 + 03), [2, 3], Some([2, 3]), Some([2, 3, 4])),
1725	            (2..(2 + 04), [2, 3], Some([2, 3]), Some([2, 3, 4])),
1726	            (2..(2 + 07), [2, 3], Some([2, 4]), Some([2, 3, 4])), // init/one differ
1727	            (2..(2 + 08), [3, 5], Some([3, 5]), Some([3, 4, 5])),
1728	            (2..(2 + 10), [3, 5], Some([3, 6]), Some([3, 5, 7])), // init/one differ
1729	            (2..(2 + 16), [4, 8], Some([4, 8]), Some([4, 6, 9])),
1730	            (2..(2 + 19), [4, 8], Some([4, 9]), Some([4, 7, 11])), // init/one differ
1731	        ];
1732	        for (range, num_init, replace_one, replace_two) in range_numbering_replacements {
1733	            let mut root = orig_root.clone();
1734	            root.numberize(id, range).unwrap();
1735	            assert_eq!(span_numbers(&root), num_init);
1736	
1737	            // Replace with a single node.
1738	            let num_result = root.replace_and_renumber(0..1, one_node);
1739	            if let Some(expected) = replace_one {
1740	                assert!(num_result.is_ok(), "numbering should succeed");
1741	                assert_eq!(span_numbers(&root), expected);
