1759	    #[test]
1760	    #[expect(clippy::zero_prefixed_literal)]
1761	    fn test_numberize_insertion() {
1762	        let id = FileId::new_for_test("numberize_insertion");
1763	        let one_node = &[SyntaxNode::leaf(SyntaxKind::Text, "X")];
1764	
1765	        let orig_root = crate::parse("A");
1766	        assert_eq!(format!("{orig_root:?}"), "Markup: 1 [Text: \"A\"]");
1767	
1768	        let back_insertion = [
1769	            // (1) The range of numbers, (2) the initial numbering for
1770	            // that range, (3) the numbers inserted at the _back_ until one of
1771	            // the spans changes.
1772	            (2..(2 + 02), [2, 3], &[] as &[u64]),
1773	            (2..(2 + 03), [2, 3], &[4]),
1774	            (2..(2 + 04), [2, 3], &[4, 5]),
1775	            (2..(2 + 07), [2, 3], &[5, 6, 7, 8]),
1776	            (2..(2 + 08), [3, 5], &[7, 8, 9]),
1777	            (2..(2 + 09), [3, 5], &[7, 8, 9, 10]),
1778	            (2..(2 + 10), [3, 5], &[7, 9, 10, 11]),
1779	            (2..(2 + 12), [3, 6], &[8, 10, 11, 12, 13]),
1780	            (2..(2 + 13), [3, 6], &[9, 11, 12, 13, 14]),
1781	            (2..(2 + 14), [3, 6], &[9, 11, 13, 14, 15]),
1782	            (2..(2 + 15), [3, 6], &[9, 11, 13, 14, 15, 16]),
1783	            (2..(2 + 16), [4, 8], &[11, 13, 15, 16, 17]),
1784	        ];
1785	        for (range, nums_init, inserted_nums) in back_insertion {
1786	            let mut expected = nums_init.to_vec();
1787	
1788	            let mut back = orig_root.clone();
1789	            back.numberize(id, range).unwrap();
1790	            assert_eq!(span_numbers(&back), expected);
1791	
1792	            expected.extend_from_slice(inserted_nums);
1793	
1794	            // Insert nodes in the back one at a time until the span number of
1795	            // one of nodes changes.
1796	            let mut prev = back.clone();
1797	            let mut n = 1;
1798	            while back.replace_and_renumber(n..n, one_node).is_ok()
1799	                && prev
1800	                    .children()
1801	                    .zip(back.children().take(n))
1802	                    .all(|(a, b)| a.span() == b.span())
1803	            {
1804	                n += 1;
