1811	            // (1) The range of numbers, (2) the initial numbering for that
1812	            // range, (3) the numbers inserted at the _front_ until one of the
1813	            // spans changes.
1814	            (2..(2 + 02), [2, 3], &[] as &[u64]),
1815	            (2..(2 + 07), [2, 3], &[]),
1816	            (2..(2 + 08), [3, 5], &[4]),
1817	            (2..(2 + 09), [3, 5], &[4]),
1818	            (2..(2 + 10), [3, 5], &[4]),
1819	            (2..(2 + 11), [3, 5], &[4]),
1820	            (2..(2 + 12), [3, 6], &[4]),
1821	            (2..(2 + 16), [4, 8], &[5]),
1822	            (2..(2 + 20), [4, 9], &[5, 6]),
1823	            // To understand these patterns, recall that the last span number
1824	            // will be the first node inserted (since we insert one at a time).
1825	            // For example, we insert 7 between 5 and 11 because we split the
1826	            // range of 5 numbers (6,7,8,9,10) in half: `5 / 2 == 2` and we
1827	            // insert `5 + 2 == 7`. We then insert 6 because it is the only
1828	            // number between 5 and 7, and we stop there since another insertion
1829	            // would be forced to modify one of the existing numbers.
1830	            (2..(2 + 24), [5, 11], &[6, 7]),
1831	            (2..(2 + 28), [5, 12], &[6, 7]),
