1839	            (2..(2 + 152), [21, 59], &[22, 24, 31]),
1840	            (2..(2 + 160), [22, 62], &[23, 25, 32]),
1841	        ];
1842	        for (range, num_init, inserted_nums) in front_insertion {
1843	            let mut expected = num_init.to_vec();
