1883	        assert_eq!(prev.offset(), 1);
1884	        assert_eq!(prev.leaf_text(), "set");
1885	    }
1886	
1887	    #[test]
1888	    fn test_linked_node_non_trivia_leaf() {
1889	        let test_id = FileId::new_for_test("test_linked_node_non_trivia_leaf");
1890	        let source = Source::new(test_id, "#set fun(12pt, red)");
1891	        let leaf = LinkedNode::new(source.root()).leaf_at(6, Side::Before).unwrap();
1892	        let prev = leaf.prev_leaf().unwrap();
